```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>Pendulum Simulation</title>
    <style>
        body {
            font-family: Arial, sans-serif;
        }
        #canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <h1>Pendulum Simulation</h1>
    <input id="input-angle" type="number" placeholder="Initial Angle (degrees)">
    <button id="release-button">Release</button>
    <canvas id="pendulum-canvas" width="400" height="400"></canvas>

    <script>
        let canvas = document.getElementById('pendulum-canvas');
        let ctx = canvas.getContext('2d');
        let gravity = 0.1;
        let angle = 0;
        let velocity = 0;
        let length = 100;
        let radius = 5;
        let initialAngle = 0;
        let released = false;

        canvas.addEventListener('click', () => {
            if (!released) {
                initialAngle = parseInt(document.getElementById('input-angle').value);
                angle = initialAngle * Math.PI / 180;
                velocity = 0;
                released = true;
            }
        });

        function draw() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.beginPath();
            ctx.arc(canvas.width / 2, canvas.height / 2, radius, 0, 2 * Math.PI);
            ctx.fillStyle = 'white';
            ctx.fill();

            let startPointX = canvas.width / 2 + Math.sin(angle) * length;
            let startPointY = canvas.height / 2 - Math.cos(angle) * length + radius;
            ctx.beginPath();
            ctx.arc(startPointX, startPointY, radius, 0, 2 * Math.PI);
            ctx.fillStyle = 'black';
            ctx.fill();

            if (released) {
                velocity += gravity;
                angle += velocity;
                if (Math.abs(angle) > Math.PI / 2) {
                    velocity = -velocity * 0.8; // add some dampening
                    if (velocity < 0.1) {
                        released = false;
                    }
                }
            }

            requestAnimationFrame(draw);
        }

        draw();

        function updateInitialAngle() {
            initialAngle = parseInt(document.getElementById('input-angle').value);
            angle = initialAngle * Math.PI / 180;
            velocity = 0;
        }

        document.getElementById('release-button').addEventListener('click', updateInitialAngle);
    </script>
</body>
</html>
```

